 async Task RefreshGpuInventory(){try{var result=await Task.Run(Native.Inventory);inventory=result.EnumerateArray().Select(g=>new GpuChoice(Native.Text(g,"id"),Native.Text(g,"name"),Native.Text(g,"vendor"),Native.Text(g,"deviceId"))).ToList();gpuChoice.ItemsSource=inventory;if(inventory.Count>0)gpuChoice.SelectedIndex=0;else Record("Nenhuma GPU física identificada pelo DXGI.",true);Record("Inventário: "+inventory.Count+" GPU(s) · "+string.Join(", ",inventory.Select(g=>g.Name)));}catch(Exception e){Record("Inventário de GPUs: "+e.Message,true);}}
